/**
 * A forex pair, by the page's own market name (`venue:EURUSD`): the two halves are both currency codes. `Pips` is the Pine's word for a
 * forex range (`cycle_labelpips`, `:254`), and the person asked for it on forex only (T-1181).
 */
const CURRENCIES = ['EUR', 'USD', 'GBP', 'JPY', 'CHF', 'AUD', 'NZD', 'CAD'];
export function isForexMarket(market: string | undefined): boolean {
  const symbol = (market ?? '').split(':').pop()?.toUpperCase() ?? '';
  return symbol.length === 6 && CURRENCIES.includes(symbol.slice(0, 3)) && CURRENCIES.includes(symbol.slice(3));
}

/**
 * The Pine's `dayofweek_label` (`GF:78-86`): the weekday of the session's start, read in New York, as its three letters. `toLocaleString`
 * would shift with the page's zone; `Intl` with the zone named is the same answer whatever the browser is set to.
 */
export function weekdayName(t: number): string {
  return new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', weekday: 'short' }).format(new Date(t));
}

/**
 * The Pine's cap (`GF:2044-2049`), **per session and not over the lot**: `Present_Mode_Box(_last)` trims each window's own array, so a
 * chart of three days keeps the newest `last` windows of every session, never `last` in total. `0` keeps none, as the Pine's `while
 * array.size > _last` with a negative count deletes them all.
 */
export function capSessionsBySession<T extends { readonly id: string }>(sessions: readonly T[], last: number): T[] {
  const size = Math.max(0, Math.min(20, Math.round(last)));
  if (size === 0) return [];
  const kept = new Set<T>();
  for (const id of new Set(sessions.map(session => session.id))) for (const session of sessions.filter(item => item.id === id).slice(-size)) kept.add(session);
  return sessions.filter(session => kept.has(session));
}

const dashOf = (border: string): readonly number[] => border === 'solid' ? [] : border === 'dashed' ? [6, 4] : [2, 3];
const flag = (params: InputValues, id: string): boolean => params[id] === true;
const text = (params: InputValues, id: string, fallback: string): string => typeof params[id] === 'string' ? params[id] : fallback;
const number = (params: InputValues, id: string, fallback: number): number => typeof params[id] === 'number' && Number.isFinite(params[id]) ? params[id] : fallback;
const priceText = (value: number): string => Number(value.toFixed(2)).toString();

export const CYCLE_90: StudyDef = {
  api: STUDY_API,
  id: 'cycle-90',
  name: '90 min cycle',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }],
  compute(ctx): StudyOutput | null {
    const series = ctx.data.candles('chart');
    if (!series || series.bars.length === 0) return null;
    const params = readInputs(INPUTS, ctx.params);
    // The Pine's timeframe gate (`OEC _Draw_Range`, called with `show90MIN and trading_mode == 'Full' and show_below_equal_15m()`):
    // `show_below_equal_15m` is `tf_m() <= 15 and timeframe.isintraday` (`GlobalFunctions:210-211`). The chart's timeframe comes from the context
    // (T-1157), never from the gap between bars — a series with a missing bar would lie about its frame.
    //
    // Absent means **no gate**: the parity harness draws a piece without naming a timeframe, and its reference has to keep measuring (T-1157);
    // a missing field that shut the drawing would turn that measurement into silence without a red test. The Pine's `trading_mode` is not
    // reproduced: this product has one mode, so there is no switch to invent here.
    const timeframe = ctx.timeframeMs;
    if (timeframe !== undefined && !(timeframe < DAY && timeframe / MINUTE <= 15)) return null;
    // The windows are always the Pine's zone (D-14, D-30): the page's zone never moves them, only their writing.
    const zone: CycleZone = CYCLE_90_ZONE;
    // A replay shows the moment it shows: the sessions are judged at that moment, never at the wall clock's.
    const now = ctx.replayAt ?? ctx.now;
    const from = Math.max(ctx.view.t0, series.bars[0]![0]), to = Math.min(ctx.view.t1, now);
    if (to <= from) return null;
    // The cycle in course, for the row that names it and counts down (T-1296): the piece publishes it, the panel never works the grid out again.
    const current = cycleAt(now, zone);
    const readout: ReadoutRow[] = current ? [{
      id: 'cycle:now', label: current.label,
      values: [
        { id: 'slot', value: current.slot }, { id: 'group', value: current.group }, { id: 'variant', value: current.variant },
        { id: 'label', value: current.label }, { id: 'from', value: current.from }, { id: 'to', value: current.to },
        { id: 'left', value: Math.round(current.leftMs / 1000) }, { id: 'share', value: cycleShare(current, now) }, { id: 'tone', value: current.tone },
        // The pill reads these two from the piece it belongs to (T-1313): they shorten what it prints and nothing else.
        { id: 'clock', value: params.clock !== false }, { id: 'countdown', value: params.countdown !== false },
      ],
    }] : [];
    const sessions = cycleSessions(series.bars, from, to, now, zone, series.heldFrom);
    if (sessions.length === 0) return readout.length ? { plots: [], readout } : null;
    const kept = capSessionsBySession(sessions, number(params, 'last', 5));
    if (kept.length === 0) return null;
    const boxOnly = text(params, 'style', 'Sandwich') === 'Box';
    const size = text(params, 'labelSize', 'Small').toLowerCase();
    const labelSize: 'tiny' | 'small' | 'normal' = size === 'tiny' ? 'tiny' : size === 'normal' ? 'normal' : 'small';
    const labelAtTop = text(params, 'labelPosition', 'Bottom') === 'Top';
    const labelOutside = text(params, 'labelSide', 'Outside') === 'Outside';
    const labels = flag(params, 'labels'), pips = flag(params, 'pips') && isForexMarket(ctx.marketId);
    const labelName = flag(params, 'labelName'), labelDay = flag(params, 'labelDay');
    const width = Math.max(0, Math.min(5, Math.round(number(params, 'width', 1))));
    // The Pine's `_opacity` is a transparency, not a solidity: it fills with `color.new(_color, _opacity)` (`GlobalFunctions library:1902`),
    // so its default 95 is a faint wash and the two crisp lines are what the eye reads.
    const fill = (100 - Math.max(0, Math.min(100, Math.round(number(params, 'fill', 95))))) / 100;
    const dash = dashOf(text(params, 'border', 'dotted'));
    const plots: Plot[] = [];
    for (const session of kept) {
      if (!flag(params, `${session.id}.on`)) continue;
      const color = text(params, `${session.id}.color`, CYCLE_SESSIONS.find(spec => spec.id === session.id)?.color ?? '#e91e63');
      if (session.high === null || session.low === null) {
        // Its start is not in the bars held: the period is drawn, its levels are not.
        plots.push({ kind: 'bgcolor', t0: session.from, t1: Math.min(session.to, now), color, alpha: fill });
        continue;
      }
      // The Pine grows the session's box while it runs: the right edge is `now` until the session ends (D-22).
      const until = session.active ? Math.min(session.to, now) : session.to;
      plots.push({ kind: 'box', t0: session.from, t1: until, p0: session.low, p1: session.high, color, width, alpha: fill });
      // The Pine's 'Sandwich' (`GF:1897-1906`): the two lines crisp over a faint fill. 'Box' leaves the box alone (`GF:1891`).
      if (!boxOnly) {
        plots.push({ kind: 'line', points: [{ t: session.from, p: session.high }, { t: until, p: session.high }], style: { color, width, dash } });
        plots.push({ kind: 'line', points: [{ t: session.from, p: session.low }, { t: until, p: session.low }], style: { color, width, dash } });
      }
      if (labels) {
        const name = text(params, `${session.id}.label`, CYCLE_SESSIONS.find(spec => spec.id === session.id)?.label ?? session.id);
        // The Pine's `Label_Range` (`GF:1823`): the text sits at the top or the bottom edge, just outside the box or just inside it. Its size is
        // the plot's own, so the painter draws it bigger or smaller without touching the words or the colour.
        //
        // The gaps are the **text's own**, in price (T-1181): a share of the box's span was 6 % of a 120-point box and 0.6 % of a 20-point one,
        // and the painter draws a label 8 px **above** the point it is handed (`painter.ts`: `fillText(..., y - 8)`), so an "outside" label
        // landed on the edge and an "inside" one under it. Pixels are translated with a nominal 600 px pane, the same nominal trend-bias declares.
        const pane = ctx.view.p1 - ctx.view.p0;
        const px = (value: number): number => (value / 600) * pane;
        const letter = labelSize === 'tiny' ? 8 : labelSize === 'normal' ? 12 : 10;
        const above = px(8) + px(letter / 2 + 2);
        const edge = labelAtTop ? session.high : session.low;
        // Outside: the whole text beyond the edge. Inside: the whole text within it. Both shifted by the painter's own 8 px lift.
        const p = labelAtTop
          ? (labelOutside ? edge + above : edge - above)
          : (labelOutside ? edge - above : edge + above);
        // `Label_Range` joins what is switched on with `' • '` (`GF:1853-1862`): the name, then the weekday of the start in New York, then the
        // range. The Pine adds `' pips'` only on a forex pair; the product prints the range and nothing else is invented here (T-1181).
        const parts = [labelName ? name : '', labelDay ? weekdayName(session.from) : '', pips ? priceText(session.high - session.low) : ''].filter(part => part !== '');
        if (parts.length) plots.push({ kind: 'label', t: session.from, p, text: parts.join(' • '), color, size: labelSize });
      }
    }
    if (plots.length === 0 && readout.length === 0) return null;
    return readout.length ? { plots, readout } : { plots };
  },
};
