/**
 * What one study's `compute()` did, as a row the console and the layers panel can read: it drew (and how many plots), it returned nothing,
 * it asked for data the page could not resolve, or it threw. Pure — no DOM, no time, no store — so `tests/studies-host.test.mts` holds it to
 * one row per study and cause.
 */
import type { StudyOutput } from '../../engine/studies/contract.ts';

/** Why a study did not draw: a thrown error; a load that failed, is on its way, or has nothing for this range; or a piece that returned nothing. */
export type StudyMiss = 'noData' | 'null' | 'error' | 'failed' | 'loading';
/** What a piece's status should say, in the panel: a failed load, one still on its way, or nothing to draw with what there is (T-1115). */
export type StudyStatus = 'failed' | 'loading' | 'empty' | null;
export interface StudyResult {
  readonly id: string;
  readonly name: string;
  /** How many plots it returned: 0 when it did not draw. */
  readonly plots: number;
  readonly miss: StudyMiss | null;
  /** The `DataReq` keys it could not resolve, or the message of a thrown error. */
  readonly data?: string;
  readonly error?: string;
}

/** The status a panel shows for a row: null when the piece drew, a word when it did not (T-1115). */
export function studyStatus(row: StudyResult | undefined): StudyStatus {
  if (!row || !row.miss) return null;
  return row.miss === 'failed' ? 'failed' : row.miss === 'loading' ? 'loading' : 'empty';
}

/** The outcome of one study from what its compute did; an output with no plots is nothing, never a drawing of zero. */
export function studyOutcome(id: string, name: string, result: {
  output: StudyOutput | null;
  error?: unknown;
  missing?: readonly string[];
  /** What the host could not resolve, with its cause (T-1115): a `#series` key that failed is not the same as one still loading. */
  misses?: readonly { readonly key: string; readonly cause: 'failed' | 'loading' | 'empty' }[];
}): StudyResult {
  if (result.error !== undefined && result.error !== null) {
    return { id, name, plots: 0, miss: 'error', error: result.error instanceof Error ? result.error.message : String(result.error) };
  }
  const plots = result.output ? result.output.plots.length : 0;
  if (plots > 0) return { id, name, plots, miss: null };
  const missing = result.missing ?? [];
  const causes = result.misses ?? [];
  const data = (causes.length ? causes.map(m => m.key) : missing).join(', ');
  // A load that failed outranks one still on its way, and both outrank "nothing for this range": the panel says the strongest cause.
  if (causes.some(m => m.cause === 'failed')) return { id, name, plots: 0, miss: 'failed', data };
  if (causes.some(m => m.cause === 'loading')) return { id, name, plots: 0, miss: 'loading', data };
  if (missing.length || causes.length) return { id, name, plots: 0, miss: 'noData', data };
  return { id, name, plots: 0, miss: 'null' };
}
