import { MAX_PREVIOUS, PERIOD_KINDS, type PeriodKind, type PeriodLines } from './levels.ts';
import { t } from '../i18n.ts';
import type { SweepStyle } from './sweep.ts';

/**
 * The Key levels' settings: whether they show, which lines of the day, the week and the month (previous high/low and previous close),
 * whether an untouched previous level runs on, and the labels at the lines' right ends and on the price axis. Days and weeks start in the
 * Volume profile's zone (`traded.zone`), so the two never disagree about when a day began.
 */
/** The eight rows of the key levels' panel (T-1079): the five intraday frames (1m, 5m, 15m, 1H, 4H), then the day, the week and the month. */
export const PREVIOUS_FRAMES = ['p1m', 'p5m', 'p15m', 'p1h', 'p4h', 'pd', 'pw', 'pm'] as const;
export type PreviousFrame = typeof PREVIOUS_FRAMES[number];
/**
 * The frames the previous-OHLC route may draw: the five intraday ones — `p1m`, `p5m`, `p15m`, `p1h` and `p4h` (T-1197, counted right in T-1213).
 * `p1m` and `p5m` share the 5 minute series on purpose: the Pine's `Intra_1m_tf` is `'5'` (`OddEyeCircle:151`), so its 1m and 5m levels are
 * the same one, and the row's name says so on screen. The day, the week and the month rows stay in the panel because
 * they are the **key levels' own** switches (they mirror into `day`, `week` and `month`), but their levels are drawn by the key levels' lines
 * and never a second time from `previousLevels` — the double previous day the person saw on 2026-11-08.
 */
export const DRAWN_FRAMES = ['p1m', 'p5m', 'p15m', 'p1h', 'p4h'] as const satisfies readonly PreviousFrame[];
/** The three rows whose lines belong to the key levels, never to the previous-OHLC frames. */
export const PERIOD_FRAMES: readonly PreviousFrame[] = ['pd', 'pw', 'pm'];

/**
 * The block's own words (`keylevels_displaystyle`, `keylevels_text`, `OEC:129-134`): the code is what a save carries and the word is what the
 * panel shows, translated where it is asked. The codes are the words' own keys, so the five are written once (T-1186).
 */
export const DISPLAY_WORDS = { Future: t('Future'), Right: t('Right') } as const;
export const TEXT_WORDS = { Tiny: t('Tiny'), Small: t('Small'), Normal: t('Normal') } as const;
/**
 * `keylevels_mode` (`OddEyeCircle:84`): how many previous periods of the day, the week and the month are drawn. `Present` takes `Last` and
 * `Historic` takes all twenty (`_cap`, `:943`); the codes are the Pine's words, so a save carries what the block calls them.
 */
export const MODE_WORDS = { Present: t('Present'), Historic: t('Historic') } as const;
export type PreviousMode = keyof typeof MODE_WORDS;
export type PreviousDisplay = keyof typeof DISPLAY_WORDS;
export type PreviousText = keyof typeof TEXT_WORDS;
const DISPLAY_CODES = Object.keys(DISPLAY_WORDS) as PreviousDisplay[];
const TEXT_CODES = Object.keys(TEXT_WORDS) as PreviousText[];
const FUTURE = DISPLAY_CODES[0]!, RIGHT = DISPLAY_CODES[1]!;
const TINY = TEXT_CODES[0]!, SMALL = TEXT_CODES[1]!, NORMAL = TEXT_CODES[2]!;

/** The previous-OHLC frames' own settings: what the piece used to keep in its panel, moved here because here is where they are drawn. */
export interface PreviousSettings {
  /** Whether the frames are drawn at all (off: the key levels are the day's, the week's and the month's own lines only). */
  on: boolean;
  /** Which frames; a frame switched off draws nothing, whatever the hierarchy says. */
  frames: Readonly<Record<PreviousFrame, boolean>>;
  /**
   * Which of each frame's levels are drawn, **one set per frame** (T-1201): the block's three boxes are per row, and one shared set made every
   * row change when another was touched. A save from before carries one set and it is read into all of them.
   */
  levels: Readonly<Record<PreviousFrame, { high: boolean; low: boolean; close: boolean }>>;
  /** The Pine's own gate: only the family the chart's timeframe belongs to is drawn (`GlobalFunctions library:192-197`). */
  follow: boolean;
  labels: boolean;
  prices: boolean;
  style: 'solid' | 'dashed' | 'dotted' | 'period';
  width: number;
  /** The Pine's `keylevels_displaystyle` and its two distances (`OEC:129-131`): Right places the level at the right edge. */
  displaystyle: PreviousDisplay;
  anchor: number;
  extend: number;
  /** The label's size (`keylevels_text`, `:134`). */
  text: PreviousText;
  /** `keylevels_globalshort` (`:135`): the code alone, or the period named before it. */
  short: boolean;
  /**
   * One colour a frame (`intra1m_css` … `monthly_css`, `OddEyeCircle:104,109,114,119,124,129,134,139`): the Pine gives each frame its own and
   * it is the colour its levels are drawn in whenever the orderflow tone does not paint over them. The defaults are the Pine's.
   */
  colors: Readonly<Record<PreviousFrame, string>>;
  /** `keylevels_compact` and its three (`:137-141`): two levels at one price are one line with both codes. */
  compact: boolean;
  compactOrderflow: boolean;
  fillOrderflow: boolean;
  /**
   * `keylevels_plot_style` (`OddEyeCircle:150`): el relleno, las marcas del barrido, o los dos. El Pine abre en `Fill`; aquí el default es
   * `both` (elección del usuario, T-1246) y es lo único que se aparta del Pine, declarado en `Notas:` de la tarjeta.
   */
  sweepStyle: SweepStyle;
  bullColor: string;
  bearColor: string;
  /**
   * Whether this panel is the one that has been touched. A save from before T-1079 kept these in `studyParams['previous-ohlc']`, and those
   * are read as they are while nobody has chosen one here — the page never quietly overwrites what somebody set.
   */
  touched: boolean;
}

export interface KeyLevelSettings extends Record<PeriodKind, PeriodLines> {
  on: boolean;
  untouched: boolean;
  /** How opaque the previous levels are drawn, in percent (100: solid). */
  opacity: number;
  /**
   * Which of the Pine's two ways of counting the drawn periods (`keylevels_mode`, `OddEyeCircle:84`): `Present` follows `last`, `Historic`
   * draws every one the Pine allows (twenty, `_cap` at `:943`).
   */
  mode: PreviousMode;
  /** `keylevels_last` (`:85`, 1..20): how many previous periods each kind draws while `mode` is `Present`. */
  last: number;
  labels: boolean;
  tags: boolean;
  /** Whether each level's label carries the date of the period it belongs to (T-1197): the Pine names it on a level that runs on, and here it can be asked for every one. */
  dates: boolean;
  previous: PreviousSettings;
}

const NONE: PeriodLines = { on: false, high: false, low: false, close: false };
/** Every frame's three boxes start with the close on and the high and low off (T-1196). */
const OFF = { high: false, low: false, close: true } as const;
/**
 * The page opens with the key levels on, and with 4H, the day, the week and the month (the user, 2026-11-26: «por defecto solo deben estar
 * activados los timeframes 4h diario semanal y mensual»). The four finer frames are one switch away in the panel.
 */
export const KEY_LEVEL_DEFAULTS: Readonly<KeyLevelSettings> = {
  on: true,
  // The person's default (T-1196): the close of each period on, its high and low off.
  day: { on: true, high: false, low: false, close: true },
  week: { on: true, high: false, low: false, close: true },
  month: { on: true, high: false, low: false, close: true },
  untouched: true,
  opacity: 100,
  // The Pine opens in `Present` with `Last` at five; here it is the same mode with three, which is what the page drew before T-1298 (D-43).
  mode: 'Present',
  last: 3,
  labels: true,
  tags: true,
  dates: false,
  // On, with 4H alone of the intraday frames (T-1302): the day, the week and the month are the key levels' own lines and draw from their rows.
  previous: {
    on: true,
    // The day, the week and the month are the key levels' own lines (T-1196): the piece adds the intraday frames only, so no period is drawn twice.
    frames: { p1m: false, p5m: false, p15m: false, p1h: false, p4h: true, pd: false, pw: false, pm: false },
    levels: {
      p1m: OFF, p5m: OFF, p15m: OFF, p1h: OFF, p4h: OFF, pd: OFF, pw: OFF, pm: OFF,
    },
    // The Pine's eight (`OddEyeCircle:104,109,114,119,124,129,134,139`): the four intraday ones share green, 4H is orange, and the day,
    // the week and the month have their own tone each.
    colors: { p1m: '#11ff40', p5m: '#11ff40', p15m: '#11ff40', p1h: '#11ff40', p4h: '#ff9800', pd: '#08bcd4', pw: '#fffcbc', pm: '#08d48c' },
    // Off by default (T-1302): the Pine's hierarchy hides an enabled frame by the chart's family, so with it on a 4H level disappears on a 1h
    // chart and the day's on a 15m one — the four the user asked for would be on and still not drawn. Off, every frame switched on draws.
    follow: false, labels: true, prices: true, style: 'period', width: 1,
    displaystyle: FUTURE, anchor: 40, extend: 250, text: SMALL, short: true,
    compact: true, compactOrderflow: true, fillOrderflow: true, sweepStyle: 'both', bullColor: '#73c3e1', bearColor: '#ffc0b2', touched: false,
  },
};

const flag = (value: unknown, fallback: boolean): boolean => typeof value === 'boolean' ? value : fallback;

/**
 * Settings from storage, field by field: whatever is missing or not valid falls back to the default.
 *
 * `defaultsRev` is the revision of the first-visit defaults the save was written under (`store.ts` `DEFAULTS_REV`), read for the one rule that
 * moves an old save once (T-1302): a save that never touched this panel and still holds the old default — the block off with the five intraday
 * frames on — is that default and not a choice, so it opens on 4H, the day, the week and the month. Any other save keeps every switch it has.
 */
export function readKeyLevels(saved: unknown, defaultsRev?: unknown): KeyLevelSettings {
  const s = (saved && typeof saved === 'object' ? saved : {}) as Partial<Record<keyof KeyLevelSettings, unknown>>, d = KEY_LEVEL_DEFAULTS;
  // One set of boxes from an older save (`previous.levels` with the three directly) stands for the **frames** (T-1203). The three period rows are
  // the key levels' own lines and keep their own boxes: the shared tern is the old shape and is **ignored for them** (T-1237), so a save from
  // before the per-row boxes opens day, week and month on the close alone — the default the person asked for — while a save that has per-row boxes
  // is read exactly as it says.
  const rawPrevious = (s.previous && typeof s.previous === 'object' ? s.previous : {}) as Record<string, unknown>;
  const rawLevels = (rawPrevious.levels && typeof rawPrevious.levels === 'object' ? rawPrevious.levels : {}) as Record<string, unknown>;
  const sharedBoxes = ('close' in rawLevels || 'high' in rawLevels || 'low' in rawLevels ? rawLevels : null);
  const sharedOf = (key: 'high' | 'low' | 'close'): boolean | null => {
    const value = sharedBoxes?.[key];
    return typeof value === 'boolean' ? value : null;
  };
  const lines = (period: PeriodKind): PeriodLines => {
    const x = (s[period] && typeof s[period] === 'object' ? s[period] : {}) as Partial<Record<keyof PeriodLines | 'prev' | 'mid' | 'open' | 'sofar', unknown>>, def = d[period];
    // Legacy: older saves used `open` for the period open; treat it as previous close. Drop mid/sofar.
    const close = typeof x.close === 'boolean' ? x.close : typeof x.open === 'boolean' ? x.open : def.close;
    // `prev` was one box for both the high and the low; a save from before it opens both, and each box is its own since T-1202.
    const prev = x.prev === true;
    // Per-row boxes are the person's choice and are read as they are (T-1237); with none, only `prev` (one box for both, the shape before
    // T-1202) and then the default stand. The shared tern never reaches these three rows any more.
    const high = flag(x.high, prev || def.high), low = flag(x.low, prev || def.low), shown = flag(close, def.close);
    // The row's switch (T-1203): a save that names it keeps it, and one from before is on when any of its boxes was.
    const on = typeof x.on === 'boolean' ? x.on : (prev || high || low || shown);
    return { on, high, low, close: shown };
  };
  const opacity = typeof s.opacity === 'number' && Number.isFinite(s.opacity) ? Math.max(10, Math.min(100, Math.round(s.opacity))) : d.opacity;
  // `keylevels_last`: 1..20, and a save from before T-1298 kept `count`, which was the same number (D-43).
  const rawLast = typeof s.last === 'number' ? s.last : (s as Record<string, unknown>).count;
  const last = typeof rawLast === 'number' && Number.isFinite(rawLast) ? Math.max(1, Math.min(MAX_PREVIOUS, Math.round(rawLast))) : d.last;
  const mode: PreviousMode = MODE_WORDS[s.mode as PreviousMode] !== undefined ? s.mode as PreviousMode : d.mode;
  // The frames: field by field, and `touched` only when a save says this panel was the one used (T-1079).
  const p = rawPrevious;
  const px = (p.frames && typeof p.frames === 'object' ? p.frames : {}) as Record<string, unknown>;
  const pl = rawLevels;
  // One set from an older save (`{ high, low, close }`) stands for every frame; a per-frame save is read frame by frame.
  const shared = sharedBoxes;

  const frames = {} as Record<PreviousFrame, boolean>;
  for (const frame of PREVIOUS_FRAMES) frames[frame] = flag(px[frame], d.previous.frames[frame]);
  const previous: PreviousSettings = {
    on: flag(p.on, d.previous.on), frames,
    levels: Object.fromEntries(PREVIOUS_FRAMES.map(frame => {
      const one = (pl[frame] && typeof pl[frame] === 'object' ? pl[frame] : shared) as Record<string, unknown> | null;
      const fallback = d.previous.levels[frame];
      return [frame, {
        high: flag(one?.high, fallback.high), low: flag(one?.low, fallback.low), close: flag(one?.close, fallback.close),
      }];
    })) as PreviousSettings['levels'],
    follow: flag(p.follow, d.previous.follow), labels: flag(p.labels, d.previous.labels), prices: flag(p.prices, d.previous.prices),
    style: p.style === 'solid' || p.style === 'dashed' || p.style === 'dotted' || p.style === 'period' ? p.style : d.previous.style,
    width: typeof p.width === 'number' && Number.isFinite(p.width) ? Math.max(1, Math.min(5, Math.round(p.width))) : d.previous.width,
    displaystyle: p.displaystyle === RIGHT ? RIGHT : FUTURE,
    anchor: typeof p.anchor === 'number' && Number.isFinite(p.anchor) ? Math.max(0, Math.min(500, Math.round(p.anchor))) : d.previous.anchor,
    extend: typeof p.extend === 'number' && Number.isFinite(p.extend) ? Math.max(5, Math.min(500, Math.round(p.extend))) : d.previous.extend,
    text: p.text === TINY ? TINY : p.text === NORMAL ? NORMAL : SMALL,
    colors: Object.fromEntries(PREVIOUS_FRAMES.map(frame => {
      const colours = (p.colors && typeof p.colors === 'object' ? p.colors : {}) as Record<string, unknown>, saved = colours[frame];
      return [frame, typeof saved === 'string' && /^#[0-9a-f]{6}$/i.test(saved) ? saved : d.previous.colors[frame]];
    })) as PreviousSettings['colors'],
    short: flag(p.short, d.previous.short),
    compact: flag(p.compact, d.previous.compact),
    compactOrderflow: flag(p.compactOrderflow, d.previous.compactOrderflow),
    fillOrderflow: flag(p.fillOrderflow, d.previous.fillOrderflow),
    sweepStyle: p.sweepStyle === 'fill' || p.sweepStyle === 'markers' ? p.sweepStyle : p.sweepStyle === 'both' ? 'both' : d.previous.sweepStyle,
    bullColor: typeof p.bullColor === 'string' && /^#[0-9a-f]{6}$/i.test(p.bullColor) ? p.bullColor : d.previous.bullColor,
    bearColor: typeof p.bearColor === 'string' && /^#[0-9a-f]{6}$/i.test(p.bearColor) ? p.bearColor : d.previous.bearColor,
    touched: p.touched === true,
  };
  const out: KeyLevelSettings = { on: flag(s.on, d.on), day: lines('day'), week: lines('week'), month: lines('month'), untouched: flag(s.untouched, d.untouched), opacity, mode, last, labels: flag(s.labels, d.labels), tags: flag(s.tags, d.tags), dates: flag(s.dates, d.dates), previous };
  // Revision 5 (T-1302): the old default, moved once. See this function's own note.
  const rev = typeof defaultsRev === 'number' ? defaultsRev : 0, prev = out.previous;
  const oldDefault = !prev.touched && !prev.on && prev.frames.p1m && prev.frames.p5m && prev.frames.p15m && prev.frames.p1h && prev.frames.p4h;
  if (rev < 5 && oldDefault) {
    return { ...out, on: true, previous: { ...prev, on: true, follow: false, frames: { ...KEY_LEVEL_DEFAULTS.previous.frames }, levels: { ...KEY_LEVEL_DEFAULTS.previous.levels } } };
  }
  return out;
}

/**
 * How many previous periods of each kind are drawn, the number `keyLines` takes. The Pine's own rule (`_cap`, `OddEyeCircle:943`): `Present`
 * takes `Last`, `Historic` takes all twenty.
 */
export const shownPeriods = (s: KeyLevelSettings): number =>
  s.mode === 'Historic' ? MAX_PREVIOUS : Math.max(1, Math.min(MAX_PREVIOUS, Math.round(s.last)));

/** Whether any line is chosen at all. */
export const anyLine = (s: KeyLevelSettings): boolean => PERIOD_KINDS.some(p => s[p].on && (s[p].high || s[p].low || s[p].close));

/** The four controls a level's row has (T-1202): its switch and the Pine's three boxes. */
export const ROW_CONTROLS = ['on', 'close', 'high', 'low'] as const;
export type RowControl = typeof ROW_CONTROLS[number];

/** The period a row of the block belongs to, or null for one of the five intraday frames (1m, 5m, 15m, 1H, 4H). */
export const periodOfRow = (frame: PreviousFrame): PeriodKind | null =>
  frame === 'pd' ? 'day' : frame === 'pw' ? 'week' : frame === 'pm' ? 'month' : null;

/**
 * What one control of one row changes (T-1203): **only that row, only that field**. The panel keeps no decision of its own — every box and every
 * switch goes through here — so a control that touches another row or another field is a bug a test catches, not something a person meets.
 *
 * A period row writes `keyLevels[period]` (its `on` and its three boxes, each its own since T-1202); an intraday row writes its own entry of
 * `previous.frames` (the switch) or `previous.levels[frame]` (a box). Nothing is mirrored and nothing is switched on by a box.
 */
export function nextRowSetting(frame: PreviousFrame, control: RowControl, checked: boolean, s: KeyLevelSettings): Partial<KeyLevelSettings> {
  const period = periodOfRow(frame);
  if (period) {
    const row: PeriodLines = { ...s[period], [control]: checked };
    return { [period]: row } as Partial<KeyLevelSettings>;
  }
  const previous = s.previous;
  if (control === 'on') return { previous: { ...previous, frames: { ...previous.frames, [frame]: checked }, touched: true } };
  const row = { ...previous.levels[frame], [control]: checked };
  return { previous: { ...previous, levels: { ...previous.levels, [frame]: row }, touched: true } };
}

/** Whether a row's switch is on: a period's own `on`, an intraday frame's entry in `frames`. */
export const rowIsOn = (frame: PreviousFrame, s: KeyLevelSettings): boolean => {
  const period = periodOfRow(frame);
  return period ? s[period].on : s.previous.frames[frame];
};

/** A row's three boxes, whichever route it belongs to. */
export const rowBoxes = (frame: PreviousFrame, s: KeyLevelSettings): { high: boolean; low: boolean; close: boolean } => {
  const period = periodOfRow(frame);
  const row = period ? s[period] : s.previous.levels[frame];
  return { high: row.high, low: row.low, close: row.close };
};
