/**
 * The candles' own painting, in one place (T-1034): the map's canvas layer draws them and the heatmap no longer does, so the chart shows one
 * set of candles instead of two stacked copies.
 *
 * Pure drawing over the options it is given: the state, the view, the plot's size, the palette and two answers the caller owns — whether the
 * trade dust is on (the candles are then outlines, so the orders show through) and which bars are unusually busy (their ring). It touches no
 * pane and asks for nothing.
 *
 * T-1318 adds what is drawn (chart-type.ts: filled, outline, OHLC bars, line) and in which colours (candle-colours.ts: the theme's until one
 * of the person's own is chosen).
 */
import type { AppState, CandleRow } from '../store.ts';
import type { View } from '../view.ts';
import type { Palette } from '../theme.ts';
import type { ChartType } from '../chart-type.ts';
import { candleInk, candleTone } from '../candle-colours.ts';
import { candleBody, footprintLayout } from '../panes/footprint.ts';
import { TIMEFRAMES } from '../hub.ts';

export interface CandlePaintOptions {
  readonly state: AppState;
  readonly view: View;
  readonly plotW: number;
  readonly plotH: number;
  readonly palette: Palette;
  /** How far the footprint's layout has taken over the slot (0 to 1); 0 without the footprint in view. */
  readonly narrowing?: number;
  /** While the trade dust shows: outline and a thin wick, never a filled body over the orders. */
  readonly hollow: boolean;
  /** Whether bar `i` is unusually busy (its volume ring, from the Highlights settings). */
  readonly hot?: (index: number) => boolean;
  /** A script's colour for the bar that starts at `t` (`$price.color`), or `''` for the theme's own (T-1058: the cable nobody read). */
  readonly color?: (t: number) => string;
  /** The bars to draw, when not the state's own (the layer draws longer ones zoomed out, zoomed-candles.ts). */
  readonly candles?: readonly CandleRow[];
  /** Their candle size in ms, with `candles`. */
  readonly barMs?: number;
  /** What to draw, when not the state's own type (the layer's longer candles). */
  readonly chartType?: ChartType;
}

/** The type whose bodies are filled; every other type is drawn hollow (outline, bars, line). */
const isFilled = (type: ChartType): boolean => type === 'candles';

/** The candles of the view as their type draws them, in the state's own colours or the theme's. */
export function paintCandles(ctx: CanvasRenderingContext2D, o: CandlePaintOptions): void {
  const { state, view: v, plotW: pw, plotH: ph, palette: p } = o;
  const candles = o.candles ?? state.candles, tf = o.barMs ?? TIMEFRAMES[state.timeframe] ?? 3_600_000;
  const type = o.chartType ?? state.chartType, colours = state.candleColors;
  const bar = Math.max(1, pw * tf / (v.t1 - v.t0));
  // With the footprint on, the candle slides to the left of its slot and keeps a solid body, the row column takes the rest.
  const narrowing = o.narrowing ?? 0, layout = footprintLayout(bar), normal = candleBody(bar);
  const body = normal + (Math.max(1, layout.body) - normal) * narrowing;
  const hot = o.hot ?? (() => false);
  // A contrasting halo keeps the price legible over both pink and green heat; it fades out over the dimmed footprint view.
  const halo = p.dark ? 'rgba(0,0,0,0.55)' : 'rgba(255,255,255,0.7)', outline = 1 - 0.85 * narrowing;
  // While the trade dust shows, or for the outline type, a candle is its outline and a thin wick: a filled body would hide the orders inside it.
  const hollow = o.hollow || type === 'outline';
  if (type === 'line') { paintLine(ctx, candles, v, ph, pw, tf, narrowing, layout, colours, p, outline, halo); return; }
  for (let ci = 0; ci < candles.length; ci++) {
    const c = candles[ci]!;
    if (c[0]! + tf < v.t0 || c[0]! > v.t1) continue;
    // Every candle, the one still forming too, has the same body and stands in the middle of its slot, so the spacing is the same all along.
    const xClassic = v.xOf(c[0]! + tf / 2, pw), x = xClassic + (v.xOf(c[0]!, pw) + layout.candleCenter - xClassic) * narrowing, up = c[4]! >= c[1]!;
    // The script's colour wins when it has one (`$price.color`); `''` is "no opinion" and the candle's own colour paints as it always did.
    const ink = candleInk(colours, up ? 'up' : 'down', p, isFilled(type), o.color?.(c[0]!) ?? '');
    const yh = v.yOf(c[2]!, ph), yl = v.yOf(c[3]!, ph), yo = v.yOf(c[1]!, ph), yc = v.yOf(c[4]!, ph), cx = Math.round(x) + 0.5;
    const top = Math.min(yo, yc), height = Math.max(1.5, Math.abs(yc - yo));
    if (type === 'bars') {
      // OHLC: the low-to-high line, the open a tick to the left and the close a tick to the right, in the body colour alone.
      const tick = Math.max(1.5, Math.min(6, body / 2));
      const path = (): void => { ctx.beginPath(); ctx.moveTo(cx, yh); ctx.lineTo(cx, yl); ctx.moveTo(cx - tick, yo); ctx.lineTo(cx, yo); ctx.moveTo(cx, yc); ctx.lineTo(cx + tick, yc); };
      ctx.globalAlpha = outline; ctx.lineWidth = 3.5; ctx.strokeStyle = halo; path(); ctx.stroke();
      ctx.globalAlpha = 1; ctx.lineWidth = 1.4; ctx.strokeStyle = ink.body; path(); ctx.stroke();
    } else if (hollow) {
      ctx.globalAlpha = 0.9; ctx.lineWidth = 1; ctx.strokeStyle = ink.wick;
      ctx.beginPath(); ctx.moveTo(cx, yh); ctx.lineTo(cx, top); ctx.moveTo(cx, top + height); ctx.lineTo(cx, yl); ctx.stroke();
      // A halo behind the whole body so an outline reads over the hottest heat (criterion 3): the heat is the background, not a surface.
      ctx.globalAlpha = outline; ctx.fillStyle = halo;
      ctx.fillRect(Math.round(x - body / 2 - 1.5) + 0.5, Math.round(top - 1.5) + 0.5, Math.max(2, Math.round(body) + 3), Math.max(2, Math.round(height) + 3));
      ctx.globalAlpha = 1; ctx.lineWidth = 1.5; ctx.strokeStyle = ink.border;
      ctx.strokeRect(Math.round(x - body / 2) + 0.75, Math.round(top) + 0.75, Math.max(1, Math.round(body) - 1.5), Math.max(1, Math.round(height) - 1.5));
    } else {
      ctx.globalAlpha = outline;
      ctx.lineWidth = 3.5; ctx.strokeStyle = halo; ctx.beginPath(); ctx.moveTo(cx, yh); ctx.lineTo(cx, yl); ctx.stroke();
      ctx.lineWidth = 1.6; ctx.strokeStyle = ink.wick; ctx.beginPath(); ctx.moveTo(cx, yh); ctx.lineTo(cx, yl); ctx.stroke();
      if (narrowing > 0.01) { ctx.globalAlpha = Math.min(1, narrowing * 1.5); ctx.lineWidth = 1.4; ctx.strokeStyle = ink.wick; ctx.beginPath(); ctx.moveTo(cx, yh); ctx.lineTo(cx, yl); ctx.stroke(); }
      ctx.lineWidth = 1;
      ctx.globalAlpha = outline; ctx.fillStyle = halo; ctx.fillRect(x - body / 2 - 1.5, top - 1.5, body + 3, height + 3);
      ctx.globalAlpha = 1; ctx.fillStyle = ink.body; ctx.fillRect(x - body / 2, top, body, height);
      if (body >= 3) { ctx.globalAlpha = outline; ctx.strokeStyle = ink.border; ctx.strokeRect(x - body / 2 + 0.5, top + 0.5, body - 1, Math.max(0.5, height - 1)); }
    }
    // Hollow or filled, a candle of unusual volume keeps its ring (Highlights).
    if (hot(ci) && type !== 'bars') {
      ctx.save(); ctx.globalAlpha = 1; ctx.shadowColor = ink.body; ctx.shadowBlur = 12; ctx.strokeStyle = ink.body; ctx.lineWidth = 2.4;
      ctx.strokeRect(x - body / 2 - 2.5, top - 2.5, body + 5, height + 5); ctx.restore();
    }
  }
  ctx.globalAlpha = 1;
}

/**
 * The chart as a line through the closes: the lightest way to see the price over the heat, a segment a candle so each one is drawn in its
 * direction's body colour, with a halo underneath so it reads over the brightest cells.
 */
function paintLine(ctx: CanvasRenderingContext2D, candles: readonly CandleRow[], v: View, ph: number, pw: number, tf: number,
  narrowing: number, layout: ReturnType<typeof footprintLayout>, colours: AppState['candleColors'], p: Palette, outline: number, halo: string): void {
  const xOf = (t: number): number => v.xOf(t + tf / 2, pw) + (v.xOf(t, pw) + layout.candleCenter - v.xOf(t + tf / 2, pw)) * narrowing;
  const path = (): void => {
    let first = true;
    for (let i = 1; i < candles.length; i++) {
      const a = candles[i - 1]!, b = candles[i]!;
      if (b[0]! + tf < v.t0 || b[0]! > v.t1) continue;
      const x0 = xOf(a[0]!), y0 = v.yOf(a[4]!, ph), x1 = xOf(b[0]!), y1 = v.yOf(b[4]!, ph);
      if (first) { ctx.moveTo(x0, y0); first = false; } else ctx.lineTo(x0, y0);
      ctx.lineTo(x1, y1);
    }
  };
  ctx.beginPath(); path(); ctx.globalAlpha = outline; ctx.lineWidth = 3.5; ctx.strokeStyle = halo; ctx.stroke();
  ctx.globalAlpha = 1; ctx.lineWidth = 1.4;
  for (let i = 1; i < candles.length; i++) {
    const a = candles[i - 1]!, b = candles[i]!;
    if (b[0]! + tf < v.t0 || b[0]! > v.t1) continue;
    const up = b[4]! >= a[4]!;
    ctx.strokeStyle = candleTone(colours, up ? 'up' : 'down', p);
    ctx.beginPath(); ctx.moveTo(xOf(a[0]!), v.yOf(a[4]!, ph)); ctx.lineTo(xOf(b[0]!), v.yOf(b[4]!, ph)); ctx.stroke();
  }
}
