/**
 * The candles as a layer of their own: canvas 0 of the map, under the heatmap, with the bars folded to the room they are given.
 *
 * The layer owns nothing: it reads the state's candles, the map's view and the plot's size, and draws. What it draws is the person's chart
 * type (`chart-type.ts`, T-1318) in their own colours (`candle-colours.ts`); narrower than `ZOOM_MIN_PX` a candle, the bars are added up into
 * longer ones (`zoomed-candles.ts`) instead of a line through the closes, so a zoomed-out chart still shows each stretch's range and side.
 *
 * The paths are built once for a key (the candles, the timeframe, the view, the plot, the theme) and only drawn again when that key changes,
 * so a frame that only moves the pointer over the map, or redraws anything above it, costs this layer nothing: it keeps what it drew.
 * Off until validated (T-1005): `main.ts` creates it only with the flag or `?candleslayer`.
 */
import { PALETTES, type Palette } from '../theme.ts';
import type { AppState, CandleRow } from '../store.ts';
import type { View } from '../view.ts';
import { TIMEFRAMES } from '../hub.ts';
import { pxPerBar } from '../candle/lod.ts';
import { ZOOM_MIN_PX, longerTf, zoomedCandles } from '../zoomed-candles.ts';
import { pageNow, replayView } from '../replay/clock.ts';
import { paintCandles } from '../candle/paint-candles.ts';

/** What the canvas holds: the key it was drawn for. */
interface Drawn { key: string }

/** What the layer is handed besides the state: the dust's hollow look, the highlights, the footprint's narrowing and a script's colours (T-1058). */
export interface CandleLayerExtras {
  readonly hollow: boolean;
  readonly hot?: (index: number) => boolean;
  /** How far the footprint's layout has taken over the slot (0 to 1); without it the bars stay in the middle and overlap the columns. */
  readonly narrowing?: number;
  /** A script's colour for the bar starting at `t` (`$price.color`), or `''` for the theme's own. */
  readonly color?: (t: number) => string;
  /** What the script's palette is keyed by, so a changed palette repaints this layer (its key otherwise says nothing changed). */
  readonly colorKey?: string;
}

export class CandlesLayer {
  /** The layer's canvas, the map pane's first: the heatmap and everything above it paint over it. */
  readonly root = document.createElement('canvas');
  #ctx: CanvasRenderingContext2D;
  /** The candles array the version counts: a new array is new data, and the last bar may also change inside the same one. */
  #bars: readonly CandleRow[] | null = null;
  #version = 0;
  #drawn: Drawn | null = null;
  #w = 0; #h = 0; #dpr = 0;

  constructor(host: HTMLElement) {
    this.root.className = 'candles';
    this.root.setAttribute('aria-hidden', 'true');
    this.#ctx = this.root.getContext('2d')!;
    host.prepend(this.root);
  }

  /**
   * Draw the candles for this state, view and plot; nothing at all when what was drawn is what this asks for. `left` is where the plot
   * starts in the pane (the columns left of the map), `dpr` the device pixel ratio.
   */
  draw(state: AppState, view: View, plotW: number, plotH: number, left: number, dpr: number, extras: CandleLayerExtras): void {
    const span = view.t1 - view.t0;
    if (!state.show.candles || !(span > 0) || plotW <= 1 || plotH <= 1) { this.#clear(); return; }
    const barMs = TIMEFRAMES[state.timeframe] ?? 3_600_000, px = pxPerBar(plotW, span, barMs);
    // Narrower than ZOOM_MIN_PX a candle, longer ones made of these (chart type Line is the person's choice and keeps its line).
    const zoomMs = state.chartType === 'line' ? barMs : longerTf(barMs, px), cut = replayView() ? pageNow() : Infinity;
    if (state.candles !== this.#bars) { this.#bars = state.candles; this.#version += 1; }
    const last = state.candles[state.candles.length - 1];
    const key = [this.#version, state.candles.length, last ? `${last[0]}:${last[4]}` : '', state.timeframe, Math.round(view.t0), Math.round(view.t1),
      view.p0, view.p1, Math.round(plotW), Math.round(plotH), Math.round(left), dpr, state.chartType, state.candleColors.up.body ?? '', state.candleColors.down.body ?? '',
      zoomMs, state.theme, extras.hollow ? 'hollow' : 'solid', state.highlight.on ? 'hot' : 'plain', extras.colorKey ?? '', Math.round((extras.narrowing ?? 0) * 1000)].join('|');
    if (this.#drawn?.key === key) return;
    this.#size(plotW, plotH, left, dpr);
    const ctx = this.#ctx, palette = PALETTES[state.theme] ?? PALETTES.light!;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, plotW, plotH);
    this.root.hidden = false;
    this.root.style.display = '';
    this.#paint(state, view, plotW, plotH, barMs, zoomMs, cut, palette, extras);
    this.#drawn = { key };
  }

  /** The canvas's own pixels, its box and where the plot starts in the pane. Only what changed is written. */
  #size(plotW: number, plotH: number, left: number, dpr: number): void {
    const w = Math.round(plotW), h = Math.round(plotH);
    if (w !== this.#w) { this.root.width = Math.round(plotW * dpr); this.root.style.width = `${plotW}px`; this.#w = w; }
    if (h !== this.#h) { this.root.height = Math.round(plotH * dpr); this.root.style.height = `${plotH}px`; this.#h = h; }
    if (dpr !== this.#dpr) { this.root.width = Math.round(plotW * dpr); this.root.height = Math.round(plotH * dpr); this.#dpr = dpr; }
    this.root.style.left = `${left}px`;
  }

  /** The bars to draw (longer ones when zoomed out) and the painter: one path, the person's type in their colours. */
  #paint(state: AppState, view: View, plotW: number, plotH: number, barMs: number, zoomMs: number, cut: number, p: Palette, extras: CandleLayerExtras): void {
    const rows = zoomMs === barMs ? state.candles : zoomedCandles(state.candles, barMs, zoomMs, null, Date.now(), cut);
    paintCandles(this.#ctx, { state, view, plotW, plotH, palette: p, hollow: extras.hollow, candles: rows, barMs: zoomMs,
      ...(extras.hot ? { hot: extras.hot } : {}), ...(extras.narrowing ? { narrowing: extras.narrowing } : {}), ...(extras.color ? { color: extras.color } : {}) });
  }

  /** Nothing to draw: the canvas is cleared once and hidden until a draw asks for it again. */
  #clear(): void {
    if (!this.#drawn && this.root.hidden) return;
    this.#ctx.setTransform(1, 0, 0, 1, 0, 0);
    this.#ctx.clearRect(0, 0, this.root.width, this.root.height);
    this.root.hidden = true;
    // A `display` from the page's own CSS wins over the `hidden` attribute, so hiding the layer needs both (T-1318: Hidden left the
    // price painted over the heat).
    this.root.style.display = 'none';
    this.#drawn = null;
  }
}
