import { PALETTES, registerPalette, resolveThemeId, type Palette } from './theme.ts';

/**
 * A theme of one's own (T-1319): the page's own token set with the person's colours on it, kept by name. It is **not** a sixteenth palette
 * beside the thirty of the box: it is the same twelve tones the page already draws with (`--bg`, `--panel`, `--line`, `--text`, `--muted`,
 * `--accent`, `--ui`, `--bid`, `--ask`, `--poc`, `--level`, `--vwap`), read over one of those palettes so the frame, the soft fills and the
 * candle colours it does not name stay the base's. Nothing here draws: the palette it builds is what `applyTheme` paints.
 */
export const CUSTOM_TOKEN_IDS = ['bg', 'panel', 'line', 'text', 'muted', 'accent', 'ui', 'bid', 'ask', 'poc', 'level', 'vwap'] as const;
export type CustomToken = (typeof CUSTOM_TOKEN_IDS)[number];

/** The tones that are read as text on a surface, and the ones that are marks: they have different AA lines (`contrastWarnings`). */
export const TEXT_TOKENS: readonly CustomToken[] = ['text', 'muted', 'accent', 'ui', 'bid', 'ask'];
export const MARK_TOKENS: readonly CustomToken[] = ['poc', 'level', 'vwap'];
/** WCAG AA: 4.5 for text, 3 for a mark that carries meaning (`tests/app-theme.test.mts` holds the box's palettes to the same lines). */
export const AA_TEXT = 4.5, AA_MARK = 3;

export const CUSTOM_PREFIX = 'custom:';
export const MAX_CUSTOM_THEMES = 12, MAX_THEME_NAME = 40;
const HEX = /^#[0-9a-f]{6}$/i;
const ID = /^custom:[a-z0-9][a-z0-9-]{0,39}$/;

export interface CustomTheme {
  /** `custom:<slug>`: what `state.theme` names, and what a layout and the page's save carry. */
  id: string;
  name: string;
  /** The palette it reads everything it does not name from. */
  base: string;
  tokens: Record<CustomToken, string>;
}

export const isHex = (value: unknown): value is string => typeof value === 'string' && HEX.test(value);
export const isCustomThemeId = (value: unknown): value is string => typeof value === 'string' && ID.test(value);

/** The twelve tones a palette is read as, as a custom theme starts them. */
export function tokensOfPalette(palette: Palette): Record<CustomToken, string> {
  const out = {} as Record<CustomToken, string>;
  for (const id of CUSTOM_TOKEN_IDS) out[id] = palette[id];
  return out;
}

/**
 * The palette a custom theme draws: its own twelve tones over its base. `null` when the base is not a palette this build knows (a file from
 * a version with a theme of its own), so the caller falls back instead of drawing a half-palette.
 */
export function customPalette(theme: CustomTheme): Palette | null {
  const base = Object.hasOwn(PALETTES, theme.base) ? PALETTES[theme.base] : null;
  if (!base) return null;
  const out: Palette = { ...base };
  for (const id of CUSTOM_TOKEN_IDS) if (isHex(theme.tokens[id])) out[id] = theme.tokens[id];
  // Whether the page is dark follows the background that was chosen, never the base's: a dark background over a light palette is a dark page,
  // and `data-theme` is what every `:root[data-theme="dark"]` rule in the style sheets reads.
  out.dark = isDarkColor(out.bg);
  return out;
}

/**
 * The page registers the person's own themes before it paints, so `applyTheme` and every pane's `setPalette` — which resolve a theme by id
 * against `PALETTES` — find them exactly as they find the box's (T-1319).
 */
export function registerCustomThemes(themes: readonly CustomTheme[]): void {
  for (const theme of themes) { const palette = customPalette(theme); if (palette) registerPalette(theme.id, palette); }
}

/** The id a name gets: its letters and digits, lower case, `custom:` in front. A name with none of them keeps a stable one. */
export function themeIdFor(name: string): string {
  const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 32);
  return `${CUSTOM_PREFIX}${slug || 'theme'}`;
}

/** The id a theme saved as `name` takes among `themes`: the first free one, and the theme being edited keeps its own. */
export function uniqueThemeId(themes: readonly CustomTheme[], name: string, keep = ''): string {
  const base = themeIdFor(name);
  let id = base, n = 2;
  while (themes.some(theme => theme.id === id && theme.id !== keep)) { id = `${base}-${n}`; n += 1; }
  return id;
}

/**
 * The themes a saved page or a file carries: a name with something in it, a base this build knows, and each tone either a `#rrggbb` or the
 * base's own. Anything else is dropped or filled in — a file can come from anywhere and from a build with fewer tones.
 */
export function readCustomThemes(raw: unknown): CustomTheme[] {
  if (!Array.isArray(raw)) return [];
  const seen = new Set<string>(), out: CustomTheme[] = [];
  for (const item of raw.slice(0, MAX_CUSTOM_THEMES)) {
    if (!item || typeof item !== 'object') continue;
    const r = item as Record<string, unknown>;
    const name = typeof r.name === 'string' ? r.name.replace(/\s+/g, ' ').trim().slice(0, MAX_THEME_NAME).trim() : '';
    if (!name) continue;
    const base = typeof r.base === 'string' && Object.hasOwn(PALETTES, r.base) ? r.base : resolveThemeId(r.base);
    const tokens = tokensOfPalette(PALETTES[base]!);
    if (r.tokens && typeof r.tokens === 'object') for (const id of CUSTOM_TOKEN_IDS) { const value = (r.tokens as Record<string, unknown>)[id]; if (isHex(value)) tokens[id] = value; }
    const saved = isCustomThemeId(r.id) && !seen.has(r.id) ? r.id : uniqueThemeId(out, name);
    if (seen.has(saved)) continue;
    seen.add(saved);
    out.push({ id: saved, name, base, tokens });
  }
  return out;
}

/** The theme a page opens on: a custom one keeps its id (the palette is registered when the page starts), anything else resolves as ever. */
export function readThemeId(raw: unknown): string {
  return isCustomThemeId(raw) ? raw : resolveThemeId(raw);
}

export interface ContrastWarning {
  token: CustomToken;
  /** The token whose colour the text or mark is drawn on: `bg` or `panel`. */
  surface: 'bg' | 'panel';
  /** The ratio the page would have, to two decimals. */
  ratio: number;
  /** The AA line it misses (4.5 for text, 3 for a mark). */
  need: number;
}

/**
 * What a set of tones would leave below AA, pair by pair: what the editor says while a colour is chosen. It **warns, never blocks** (the
 * user's rule): the page knows `--ui` 3.41 and `--bid`/`--ask` 3.00 in its own light palette do not pass as text, and a theme that repeats
 * them is their choice.
 */
export function contrastWarnings(tokens: Record<CustomToken, string>): ContrastWarning[] {
  const out: ContrastWarning[] = [];
  const surfaces = ['bg', 'panel'] as const;
  for (const surface of surfaces) {
    const under = tokens[surface];
    for (const token of TEXT_TOKENS) if (isHex(tokens[token]) && isHex(under)) {
      const ratio = contrast(tokens[token], under);
      if (ratio < AA_TEXT) out.push({ token, surface, ratio, need: AA_TEXT });
    }
    for (const token of MARK_TOKENS) if (isHex(tokens[token]) && isHex(under)) {
      const ratio = contrast(tokens[token], under);
      if (ratio < AA_MARK) out.push({ token, surface, ratio, need: AA_MARK });
    }
  }
  return out;
}

/** Whether a colour is dark enough to be the background of a dark page, at the line `tests/app-theme.test.mts` holds the box's palettes to. */
export function isDarkColor(hex: string): boolean {
  const n = parseInt(hex.slice(1), 16);
  const channel = (v: number): number => { const c = v / 255; return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
  return 0.2126 * channel(n >> 16 & 255) + 0.7152 * channel(n >> 8 & 255) + 0.0722 * channel(n & 255) < 0.18;
}

/** WCAG contrast of two `#rrggbb` colours (`theme.ts` keeps its own for its own reasons; this one is pure and takes no palette). */
export function contrast(a: string, b: string): number {
  const lum = (hex: string): number => {
    const n = parseInt(hex.slice(1), 16), channel = (v: number): number => { const c = v / 255; return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
    return 0.2126 * channel(n >> 16 & 255) + 0.7152 * channel(n >> 8 & 255) + 0.0722 * channel(n & 255);
  };
  const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x) as [number, number];
  return Math.round(((hi + 0.05) / (lo + 0.05)) * 100) / 100;
}
