import { el } from './dom.ts';
import { t } from './i18n.ts';
import { PALETTES } from './theme.ts';
import type { Store } from './store.ts';
import { CHART_HIDDEN, CHART_TYPES, chartChoiceOf, chartChoicePatch, chartTypeName, chartTypeTip, type ChartChoice } from './chart-type.ts';
import { CANDLE_COLORS_DEFAULT, CANDLE_DIRECTIONS, CANDLE_PARTS, hasCandleColors, themeBody, themeEdgeHex, withCandleColor, type CandleDirection, type CandlePart } from './candle-colours.ts';

/**
 * The Chart type buttons and the Candle colours grid, in the Chart settings (T-1318, ported from the original's `candle-colours-panel.ts`):
 * filled, outline, OHLC bars, line and Hidden; and body, border and wick for rising and falling candles, the theme's until one is chosen.
 * Kept out of `toolbar.ts` so the bar's own file does not grow a second panel, and because the panel is what the bar opens.
 */

/** The type's buttons: a type draws the price that way (bringing it back from Hidden); Hidden takes it off the map. */
export function chartTypeRow(store: Store): HTMLElement {
  const root = el('div', { class: 'seg chart-type', role: 'group' });
  root.setAttribute('aria-label', t('Chart type'));
  const draw = (): void => {
    const s = store.state, rows: { choice: ChartChoice; name: string; tip: string }[] = [
      ...CHART_TYPES.map(type => ({ choice: type as ChartChoice, name: chartTypeName(type), tip: chartTypeTip(type) })),
      { choice: CHART_HIDDEN, name: t('Hidden'), tip: t('Take the price off the map: the heatmap and the trade bubbles stay, with nothing on top.') },
    ];
    root.replaceChildren(...rows.map(row => {
      const on = chartChoiceOf(s.chartType, s.show.candles) === row.choice;
      const button = el('button', { type: 'button', class: on ? 'on' : '', textContent: row.name, tip: row.tip, onclick: () => { store.set(chartChoicePatch(row.choice, store.state.show)); draw(); } });
      button.setAttribute('aria-pressed', String(on));
      return button;
    }));
  };
  draw();
  return root;
}

/** The candles' own colours: a row a part, a column a direction, each the theme's until the person chooses one. */
export function candleColoursRow(store: Store): HTMLElement {
  const root = el('div', { class: 'candle-colours' });
  const partName = (part: CandlePart): string => ({ body: t('Body'), border: t('Border'), wick: t('Wick') })[part];
  const draw = (): void => {
    const s = store.state, p = PALETTES[s.theme] ?? PALETTES.light!, filled = s.chartType === 'candles' || s.chartType === 'line';
    const body = (d: CandleDirection): string => s.candleColors[d].body ?? themeBody(d, p);
    const shown = (d: CandleDirection, part: CandlePart): string => s.candleColors[d][part] ?? (part === 'body' ? body(d) : filled ? themeEdgeHex(p) : body(d));
    const rows = CANDLE_DIRECTIONS.map(direction => el('div', { class: 'row' },
      el('span', { class: 'muted', textContent: direction === 'up' ? t('Rising') : t('Falling') }),
      ...CANDLE_PARTS.map(part => {
        const input = el('input', { type: 'color', value: shown(direction, part), ariaLabel: `${direction === 'up' ? t('Rising') : t('Falling')} ${partName(part)}` });
        input.oninput = () => store.set({ candleColors: withCandleColor(store.state.candleColors, direction, part, input.value) });
        return el('label', { class: 'field' }, el('span', { class: 'name', textContent: partName(part) }), input);
      })));
    root.replaceChildren(...rows,
      el('p', { class: 'sheet-note', textContent: t('A part left at the theme\'s colour follows the theme. The price line and its tag take the body colour.') }),
      ...(hasCandleColors(s.candleColors)
        ? [el('button', { type: 'button', textContent: t('Reset candle colours'), tip: t('Every candle colour back to the theme\'s.'),
          onclick: () => { store.set({ candleColors: CANDLE_COLORS_DEFAULT }); draw(); } })]
        : []));
  };
  draw();
  return root;
}
