/**
 * The host the registered studies read their data from: `DataReq` resolved from what the page already holds, never from a new source.
 *
 * - `chart` is the chart's own series (`state.candles`), the series every pane already draws.
 * - `series:<tf>` (`5`, `15`, `60`, `240`, `D`, `W`, `M`) is that series when the chart is on that timeframe; otherwise the same candles the
 *   key levels and the VWAP already read from the exchange through `hub.vwapHistory`, loaded by the KeyLevelHistory the page keeps per bar
 *   size (no new endpoint, no new kind of request).
 * - `ltf` is the minute series under a coarser chart, from the same loader the key levels and the VWAP read (`hub.vwapHistory(60_000)`,
 *   `hub.ts:215`): the piece that asks for it (`bookmap-trigger`) groups those bars into the chart bar by their start. A chart already at a
 *   minute or finer has nothing under it and the page holds no sub-minute OHLC, so `ltf` is null there and says why; the trade tape's
 *   per-second prices are never turned into bars (`hub.flow` `ownPrice` has no open or close).
 * - Anything else (`prints`) is not resolved here on purpose: a study that asks for it draws nothing rather than being handed another series,
 *   and the miss is said once in the console.
 *
 * `paintRegisteredStudies` is the one call the map makes: it computes every registered study except the VWAP (that one has its own adapter
 * with settings and anchors) and paints them on the map's canvas with the engine's painter.
 */
import type { AppState, CandleRow } from '../store.ts';
import type { Hub } from '../hub.ts';
import { TIMEFRAMES } from '../hub.ts';
import type { Bounds } from '../view.ts';
import type { Palette } from '../theme.ts';
import type { Scope } from '../../engine/draw/scope.ts';
import { paintStudies } from '../../engine/draw/painter.ts';
import type { ReadoutRow, StudyCandles, StudyData, StudyOutput, StudyPalette, StudySums } from '../../engine/studies/contract.ts';
import { readInputs } from '../../engine/inputs/schema.ts';
import { studies } from '../../engine/studies/registry.ts';
import { historyTarget } from '../keylevels/history.ts';
import { barMsFor } from '../keylevels/levels.ts';
import type { KeyTag } from '../keylevels/paint.ts';
import { currentCoin } from '../coin.ts';
import { pageNow, replaying } from '../replay/clock.ts';
import { zoneId, zoneName } from '../format.ts';
import { studyOutcome, type StudyResult } from './outcome.ts';
import { studyOn } from './switches.ts';
import { adverseOn, adverseReadout } from '../dev/adverse.ts';
import { studyAlpha } from './opacity.ts';

/** The bar size `ltf` is read at: a minute under any coarser chart, and null when the chart is already a minute or finer (no sub-minute OHLC is held). */
export function ltfBarMs(chartBarMs: number): number | null { return chartBarMs > 60_000 ? 60_000 : null; }

/** The bar sizes a study names in `series:<tf>`, as the Pine names them. */
const SERIES_MS: Readonly<Record<string, number>> = { '5': 300_000, '15': 900_000, '60': 3_600_000, '240': 14_400_000, D: 86_400_000, W: 604_800_000, M: 2_592_000_000 };
/** The studies this host does not compute: the VWAP has its own adapter (settings, anchors, whale sums). */
const OWN_ADAPTER = 'vwap';
/** The pieces the deck's own lamp switches, instead of a row in its panel (T-1295: the HTF candles are drawn on the map, `show.htf` is the switch). */
export const LAMPED: ReadonlyMap<string, keyof AppState['show']> = new Map([['htf-candles', 'htf']]);

export class StudyHost implements StudyData {
  #said = new Set<string>();
  /** Bars of history the chart series owes this piece before the first one it draws (T-1232), from its own `data` declaration. */
  #warmup = 0;
  constructor(private state: AppState, private hub: Hub, private invalidate: () => void) {}
  /** The warm-up the piece asks for, read from its `data` by whoever knows the study (`paintRegisteredStudies`). */
  setWarmup(bars: number): this { this.#warmup = Math.max(0, Math.round(bars)); return this; }

  candles(key: string, backMs?: number): StudyCandles | null {
    const series = this.#resolve(key, backMs);
    return series && series.bars.length >= 2 ? series : null;
  }

  /** No registered study asks for the large-order sums yet; when one does, it is a miss, not a guess. */
  sums(key: string): StudySums | null { this.#miss(key, 'empty'); return null; }

  /** Another study's output of this frame (T-1237). The pass fills it; a piece asking for one that did not run gets null, never a copy. */
  study(id: string): StudyOutput | null { return this.#published.get(id) ?? null; }
  #published: ReadonlyMap<string, StudyOutput> = new Map();
  /** The outputs the pass has published so far, shared by every host it hands to a piece (T-1237). */
  setPublished(published: ReadonlyMap<string, StudyOutput>): this { this.#published = published; return this; }

  #resolve(key: string, backMs?: number): StudyCandles | null {
    if (key === 'chart') return this.#own(this.#warmup);
    if (key === 'ltf') return this.#lower(backMs);
    const name = key.startsWith('series:') ? key.slice('series:'.length) : null;
    const bar = name ? SERIES_MS[name] : undefined;
    if (bar === undefined) { this.#miss(key, 'empty'); return null; }
    const tf = TIMEFRAMES[this.state.timeframe] ?? 3_600_000;
    if (bar === tf) return this.#own();
    return this.#history(bar, key, backMs);
  }

  /** The minute series under the chart: from the same loader the key levels use, or nothing when the chart has nothing under it. */
  #lower(backMs?: number): StudyCandles | null {
    const bar = ltfBarMs(TIMEFRAMES[this.state.timeframe] ?? 3_600_000);
    if (bar === null) { this.#miss('ltf', 'empty'); return null; }
    // The stretch the piece asks for travels to the loader (T-1195): the bookmap cuts its bins over the last few hundred chart bars, and the
    // loader's default (the two periods before the view) would hand it a handful of minutes. Without the hint nothing changes.
    return this.#history(bar, 'ltf', backMs);
  }

  /**
   * The chart's own bars, and the warm-up a piece needs before them (T-1232). The view's bars are `state.candles`; the warm-up is read from the same
   * exchange history the other series use, at the chart's own bar size, and put **in front** of them: the painter draws the view, the piece counts
   * from the earlier bars. Without enough history the view alone is handed back, so the piece says what it is missing instead of drawing nothing.
   */
  #own(warmup = 0): StudyCandles | null {
    const bars = this.state.candles;
    if (bars.length < 2) return null;
    if (warmup <= 0) return { bars, heldFrom: bars[0]![0], liveFrom: Infinity };
    const barMs = TIMEFRAMES[this.state.timeframe] ?? 3_600_000;
    // A **stretch**, not a timestamp: `#history` reads it as `backMs` and asks for `pageNow() - backMs` on. `viewFrom + warmup × bar` is an epoch
    // value, so the ask went off to 1970 and the loader answered with nothing usable (T-1233).
    const span = Math.max(0, pageNow() - this.#viewFrom()) + warmup * barMs;
    const history = this.#history(barMs, 'chart', span);
    if (!history || history.bars.length < 2) return { bars, heldFrom: bars[0]![0], liveFrom: Infinity };
    // Only what is **before** the view: a bar the chart already has is the chart's, not the loader's.
    const first = bars[0]![0];
    const before = history.bars.filter(row => row[0] < first);
    if (!before.length) return { bars, heldFrom: bars[0]![0], liveFrom: Infinity };
    return { bars: [...before, ...bars], heldFrom: before[0]![0], liveFrom: Infinity };
  }

  /** A coarser or finer series from the same exchange history the key levels read, asked for the two periods before the view. */
  #history(bar: number, key: string, backMs = 0): StudyCandles | null {
    const target = historyTarget(this.state.seriesInstrument || this.state.marketId, currentCoin());
    if (!target) { this.#miss(key, 'empty'); return null; }
    // A piece that draws N candles of this bar size asks for that stretch back (T-1173); one that asks for nothing keeps the two periods
    // before the view it always got, so no other piece changes.
    const from = Math.min(this.#viewFrom(), pageNow() - backMs) - 2 * bar;
    const history = this.hub.vwapHistory(bar);
    history.ensure(target, Math.max(0, from), bar, this.invalidate);
    // A loader that could not read is a **failure**; one that has not answered yet is **loading**; both used to look like an empty
    // chart (T-1115). `history.state` is the loader's own word: idle, loading, ready or unavailable.
    if (history.id !== target.id || history.barMs !== bar || !history.bars.length) {
      this.#miss(key, history.state === 'unavailable' ? 'failed' : 'loading');
      return null;
    }
    return { bars: history.bars as readonly CandleRow[], heldFrom: history.heldFrom, liveFrom: Infinity };
  }

  #viewFrom(): number { return this.#view?.t0 ?? 0; }
  #view: Bounds | null = null;
  /** The view the ask is for (the two periods before it decide how far back to load). */
  setView(view: Bounds): this { this.#view = view; return this; }

  /** The keys this host could not resolve and **why**, in the order they were asked (T-1115): a study that draws nothing says which, and if
   * the reason was a failed load, one still on its way, or a range with nothing. */
  #missing: { key: string; cause: 'failed' | 'loading' | 'empty' }[] = [];
  missing(): readonly string[] { return this.#missing.map(entry => entry.key); }
  misses(): readonly { readonly key: string; readonly cause: 'failed' | 'loading' | 'empty' }[] { return this.#missing; }
  #miss(key: string, cause: 'failed' | 'loading' | 'empty'): void {
    if (this.#said.has(key)) return;
    this.#said.add(key);
    this.#missing.push({ key, cause });
  }
}

export interface StudiesScope {
  readonly state: AppState;
  readonly hub: Hub;
  readonly view: Bounds;
  readonly width: number;
  readonly height: number;
  readonly palette: Palette;
  readonly board: Scope['board'];
  readonly invalidate: () => void;
  /** What the right-hand axis and columns take, in CSS px (T-1166): the pane knows it, a piece does not. */
  readonly gutterRight?: number;
}

/** The last frame's outcomes, for the layers panel: the panel does not compute, it reads this. */
let report: readonly StudyResult[] = [];
export function studiesStatus(): readonly StudyResult[] { return report; }


/** The previous-OHLC frames a study published this frame, as the key-level painter wants them (T-1068): prices and dates, never a model. */
export interface StudyFrame { readonly frame: string; readonly code: string; readonly price: number; readonly from: number; readonly to: number; readonly color: string }
let frames = new Map<string, readonly StudyFrame[]>();
export function studyFrames(id: string): readonly StudyFrame[] { return frames.get(id) ?? []; }

/** The last frame's named numbers, per study, for the panels that read them (D-31): a panel never recomputes what the piece drew. */
let readouts = new Map<string, readonly ReadoutRow[]>();
export function studyReadout(id: string): readonly ReadoutRow[] {
  // The panel pass (T-1178): a development build opened with `?adverse=1` reads the worst-case dataset through this same door.
  const adverse = adverseOn() ? adverseReadout(id) : null;
  return adverse ?? readouts.get(id) ?? [];
}

/** Said once per change, never per frame: a study that keeps failing keeps its line out of the console. */
let said = '';
function reportStudies(rows: readonly StudyResult[]): void {
  report = rows;
  const key = rows.map(row => `${row.id}:${row.miss ?? 'ok'}:${row.data ?? ''}:${row.error ?? ''}`).join('|');
  if (key === said) return;
  said = key;
  for (const row of rows) {
    if (!row.miss) continue;
    console.info(row.miss === 'error' ? `[studies] ${row.id}: error: ${row.error}`
      : row.miss === 'failed' ? `[studies] ${row.id}: could not read ${row.data}`
      : row.miss === 'loading' ? `[studies] ${row.id}: still reading ${row.data}`
      : row.miss === 'noData' ? `[studies] ${row.id}: no data for ${row.data}`
      : `[studies] ${row.id}: returned nothing`);
  }
}

/** A 2D context kept for measuring: the painter's own font, so a piece lays a line out as it will be drawn (T-1166). */
let measureCtx: CanvasRenderingContext2D | null = null;
function measureText(text: string, px: number): number {
  if (!measureCtx) measureCtx = document.createElement('canvas').getContext('2d');
  if (!measureCtx) return text.length * px * 0.8;
  measureCtx.font = `600 ${px}px ui-sans-serif, system-ui, sans-serif`;
  return measureCtx.measureText(text).width;
}

/** The colours a study may ask for, from the map's palette. */
function studyPalette(p: Palette): StudyPalette { return { dark: p.dark, vwap: p.vwap, bid: p.bid, ask: p.ask, panel: p.panel }; }

/** The chart market's price step (`syminfo.mintick`): from the market the page holds, or `null` — a market that does not carry it is not guessed. */
function chartTickSize(state: AppState): number | null {
  const id = state.seriesInstrument || state.marketId;
  const market = state.markets.find(item => (item.instrumentId ?? item.id) === id);
  const tick = market?.tickSize;
  return typeof tick === 'number' && Number.isFinite(tick) && tick > 0 ? tick : null;
}

/** Every registered study there is, computed against what the page holds and painted: the tags go to the axis like the VWAP's. */
export function paintRegisteredStudies(ctx: CanvasRenderingContext2D, o: StudiesScope): KeyTag[] {
  const palette = studyPalette(o.palette), outputs: { output: StudyOutput; alpha: number }[] = [], rows: StudyResult[] = [], named = new Map<string, readonly ReadoutRow[]>(), drawn = new Map<string, readonly StudyFrame[]>();
  // What each study of this pass computed, served to the studies after it by id (T-1237): the registry's order is the order of the pass, and the
  // bookmap sits before ST entry, so the piece that draws the bubbles answers the piece that reads them in the same frame, with no second calculation.
  const published = new Map<string, StudyOutput>();
  for (const study of studies()) {
    const lamped = LAMPED.get(study.id);
    const on = lamped ? o.state.show[lamped] : studyOn(o.state.studySwitches, study.id);
    // The cycle keeps publishing while it is switched off (T-1313): its switch governs **the drawing on the chart**, never the data. A widget in
    // the bar that said «apagado» was showing an absence that does not exist — the clock is inside a window whether or not the lines are drawn —
    // and the switch itself is the bar's click (T-1312), so the row must read the cycle either way.
    if (study.id === OWN_ADAPTER || (!on && study.id !== 'cycle-90')) continue;
    // A study that throws is caught here: its row says so and the others draw as usual.
    const warmup = study.data.find(req => req.key === 'chart')?.warmup ?? 0;
    const host = new StudyHost(o.state, o.hub, o.invalidate).setView(o.view).setWarmup(warmup).setPublished(published);
    let output: StudyOutput | null = null, error: unknown = null;
    try {
      output = study.compute({
        params: readInputs(study.inputs, o.state.studyParams[study.id] ?? null), data: host, view: o.view, now: pageNow(), zone: zoneId(), coin: currentCoin().coin,
        // The market the chart is on, for the pieces with a forex-only word (T-1181): the instrument the page names, never a guess from the coin.
        marketId: o.state.seriesInstrument || o.state.marketId,
        // The chart's timeframe, for the pieces whose Pine gates on it (T-1157): the page's own setting, never the gap between bars.
        timeframeMs: TIMEFRAMES[o.state.timeframe] ?? 3_600_000,
        // The line is measured by the pane's own context, and the right-hand columns are a share of the pane, not a guess (T-1166).
        measureText,
        gutterRight: o.width > 0 ? (o.gutterRight ?? 0) / o.width : 0,
        tickSize: chartTickSize(o.state),
        windows: [], anchors: [], zoneBarMs: barMsFor(zoneId(), o.view.t0, o.view.t1), replayAt: replaying() ? pageNow() : null, palette,
      });
    } catch (caught) { error = caught; }
    // Switched off, the cycle answers with its numbers and no drawing: what the switch owns is the lines, not the reading.
    if (!on && output) output = { ...output, plots: [], labels: [], tags: [] };
    // A study that returned nothing publishes nothing: a piece that reads it is told it did not answer, never handed an empty list.
    if (output) published.set(study.id, output);
    rows.push(studyOutcome(study.id, study.name, { output, error, missing: host.missing(), misses: host.misses() }));
    // What the panel reads: the piece's own numbers, never a second calculation (D-31). A piece with nothing to say says nothing.
    if (output?.readout?.length) named.set(study.id, output.readout);
    if (output?.readout?.length) {
      const framesOf: StudyFrame[] = [];
      for (const row of output.readout) {
        if (!row.id.startsWith('frame:')) continue;
        const values = new Map(row.values.map(value => [value.id, value.value])), [, frame = ''] = row.id.split(':');
        const price = values.get('price'), from = values.get('from'), to = values.get('to'), color = values.get('color');
        if (typeof price !== 'number' || typeof from !== 'number' || typeof to !== 'number' || typeof color !== 'string') continue;
        framesOf.push({ frame, code: row.label, price, from, to, color });
      }
      if (framesOf.length) drawn.set(study.id, framesOf);
    }
    // Each piece draws at its own opacity (T-0046), on top of the layer's: 0 means it is on but invisible, and it is not painted at all.
    if (output) { const alpha = studyAlpha(o.state, study.id); if (alpha > 0) outputs.push({ output, alpha }); }
  }
  reportStudies(rows);
  readouts = named; frames = drawn;
  if (!outputs.length) return [];
  // One paint a piece, so its own alpha reaches only its plots; the tags still share the layer's one board and come back together.
  const tags: { key: string; price: number; rank: number; text: string; color?: string | undefined }[] = [];
  for (const drawn of outputs) {
    ctx.save(); ctx.globalAlpha *= drawn.alpha;
    tags.push(...paintStudies(ctx, [drawn.output], { view: o.view, width: o.width, height: o.height, palette, board: o.board }));
    ctx.restore();
  }
  return tags.map(tag => ({ key: tag.key, y: (1 - (tag.price - o.view.p0) / (o.view.p1 - o.view.p0)) * o.height, rank: tag.rank, text: tag.text, older: false, color: tag.color }));
}
